/* ========== TOPBAR I FEM TRIN, HJÆLP OG TOOLTIPS ========== */
/* Topbaren har fem rækker. Række 1 er altid synlig (fil, Afspil, Fest!, en opsætning, Hjælp). Hvert trin (1 til 5) viser én række mere med flere, mere avancerede knapper. Valget huskes. */
/* Menuer i topbaren: fem menuer med overskrifter; kun én er åben ad gangen; Escape, et klik udenfor eller at tabbe væk lukker; en menu viser en grøn prik, når noget i den er tændt. */
function mnLuk(undtagen){document.querySelectorAll('#tb .menup').forEach(p=>{if(p!==undtagen&&!p.hidden){p.hidden=true;const b=$('mn-'+p.id.slice(3));if(b)b.setAttribute('aria-expanded','false')}})}
function mnToggle(b,tast){const p=$(b.getAttribute('aria-controls'));if(!p)return;const aaben=p.hidden;mnLuk(aaben?p:null);p.hidden=!aaben;b.setAttribute('aria-expanded',aaben?'true':'false');if(aaben&&tast){const f=p.querySelector('button,select,input');if(f)f.focus()}}
document.querySelectorAll('#tb .menub').forEach(b=>b.addEventListener('click',e=>mnToggle(b,e.detail===0)));
document.addEventListener('click',e=>{if(!e.target.closest('#tb .menu'))mnLuk(null);else if(e.target.closest('.menup button'))setTimeout(()=>mnLuk(null),0)},true);
document.addEventListener('change',e=>{if(e.target.tagName==='SELECT'&&e.target.closest&&e.target.closest('#tb .menup'))setTimeout(()=>mnLuk(null),0)});
document.addEventListener('focusin',e=>{if(!e.target.closest('#tb .menu'))mnLuk(null)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const o=document.querySelector('#tb .menup:not([hidden])');if(o){const b=$('mn-'+o.id.slice(3));mnLuk(null);if(b)b.focus();e.preventDefault()}}});
function mnPrikker(){document.querySelectorAll('#tb .menub').forEach(b=>{const p=$(b.getAttribute('aria-controls'));const taendt=!!(p&&p.querySelector('[aria-pressed="true"],input[type=checkbox]:checked'));if(taendt)b.dataset.on='';else delete b.dataset.on})}
$('file').addEventListener('change',e=>{const f=e.target.files&&e.target.files[0];$('tb-filtekst').textContent=f?f.name:'Vælg lydfil'});
/* Opslag i manualen fra en knap: åbn manualen og gå til afsnittet (id: man-<navn>) */
function manualAabn(nøgle){try{if(!$('gd').open)$('gd').showModal()}catch(e){}manualGaa('man-'+nøgle)}
/* Genveje i topbaren er kopier af de rigtige knapper og lister: de kalder det samme, og deres tekster følger de rigtige. */
document.addEventListener('change',e=>{const t=e.target,k=t.dataset&&t.dataset.ms;if(!k)return;const via=(id)=>{const o=$(id);if(o&&t.value){o.value=t.value;o.dispatchEvent(new Event('change',{bubbles:true}))}t.value=''};
 if(k==='tb-ops')via('mb-ops-sel');else if(k==='tb-mine')via('mb-mine-sel');else if(k==='tb-kval')kvVaelg(t.value);
 else if(k==='tb-reg'){const o=$('kv-reg');if(o){o.checked=t.checked;o.dispatchEvent(new Event('change',{bubbles:true}))}}});
function topSync(){if(!document.getElementById('tb'))return;const nu=performance.now();if(nu-(topSync.t||0)<250)return;topSync.t=nu;
 const kop=(a,b)=>{const x=$(a),y=$(b);if(x&&y&&x.dataset.sig!==y.dataset.sig+'|'+y.options.length){x.innerHTML=y.innerHTML;x.dataset.sig=y.dataset.sig+'|'+y.options.length;x.value=''}};
 kop('tb-ops','mb-ops-sel');kop('tb-mine','mb-mine-sel');
 const kv=$('tb-kval');if(kv&&kv!==document.activeElement)kv.value=Rytme.kvalKopi(set.kval).niveau;const rg=$('tb-reg');if(rg)rg.checked=!!set.kval.regulator;
 const mv=$('tb-mv');if(mv&&mv.textContent!==$('mvbtn').textContent)mv.textContent=$('mvbtn').textContent;
 const db=$('dubbtn');if(db){const t='Dublet: '+(typeof dubSynlig==='function'&&dubSynlig()?'Til':'Fra');if(db.textContent!==t)db.textContent=t}const rtb=$('rtbtn');if(rtb){const t='Routing-overblik: '+(typeof rtSynlig==='function'&&rtSynlig()?'Til':'Fra');if(rtb.textContent!==t)rtb.textContent=t}mnPrikker()}
/* ---- Ordbog: vises under ? Hjælp, med søgning ---- */
const ORDBOG=[
['Lyd og måling','Lydtræk','Alt programmet måler i musikken, og en forbindelse kan læse: et tal fra 0 til 1 for hvert billede. Der er 14 lydtræk (Bas, Mid, Høj-mid, Brillians, RMS, Spectral centroid, Spectral flux, Spectral rolloff, Spectral flatness, Zero crossing rate, tre slagdetektorer og Vokal) og 51 analysekilder (toneklasser, grundtone, klang og log-spektrum).'],
['Lyd og måling','Frekvensbånd','De lydtræk, der måler et område af tonehøjde: Bas (20 til 250 Hz), Mid (250 til 2000 Hz), Høj-mid (2 til 6 kHz) og Brillians (6 til 16 kHz), samt log-spektrets 31 tredjedelsoktavbånd. Vokal måler også 200 til 900 Hz, men energien tæller mindre, jo mere støjende lyden er (den er ganget med 1 minus tre gange fladheden), så den er ikke en ren stemmedetektor. De andre lydtræk er ikke frekvensbånd.'],
['Lyd og måling','Niveau (RMS)','Den gennemsnitlige lydstyrke (energi) over hele spektret. Jævn og god til fart og lysstyrke. Står i listerne som RMS.'],
['Lyd og måling','Ændring (flux)','Hvor meget lydens spektrum ændrer sig fra billede til billede. Højt ved nye anslag, lavt ved en jævn tone. Står i listerne som Spectral flux.'],
['Lyd og måling','Spektralt tyngdepunkt (centroid)','Hvor lyden "ligger": en mørk lyd har lavt tyngdepunkt, en lys og skarp lyd højt. Godt til farve.'],
['Lyd og måling','Rolloff','Den frekvens, som 85 % af lydens energi ligger under. Stiger, når der er meget diskant.'],
['Lyd og måling','Fladhed (flatness)','Tæt på 1 er støj (som en hihat), tæt på 0 er en ren tone (som en stemme). Godt til usikkerhed.'],
['Lyd og måling','Nulgennemgange (zero crossing rate)','Hvor tit signalet krydser nul. Højt for skarpe, støjende lyde.'],
['Lyd og måling','Slagdetektor / anslag','Slag, dyb (kick), Slag, midt (snare) og Slag, høj (hihat) måler stigninger i energi i bas, høj-mid og brillians. De ser, at der kommer et slag, men genkender ikke trommer (kun stigninger tæller, ikke vedvarende lyd).'],
['Lyd og måling','Normalisering','Skalerer alle lydtræk til 0 til 1. Auto deler med sangens 99. percentil (så hver sang udnytter hele skalaen); Fast bruger en fast reference, så sange kan sammenlignes.'],
['Lyd og måling','Spektrum (FFT)','Et regnestykke, der deler lyden op efter tonehøjde, så man kan se, hvor meget der er i bassen, midten og diskanten.'],
['Lyd og måling','Log-spektrum (tredjedelsoktavbånd)','31 bånd fra 20 Hz til 20 kHz, delt, som øret hører: lige store trin i tonehøjde. Bassen kan skelnes, fordi analysen bruger et langt vindue.'],
['Toner og klang','Grundtone (tonehøjde)','Den dybeste tone i en lyd, i Hz (fx A4 = 440 Hz), med en sikkerhed fra 0 til 1. Pålidelig for en enkelt stemme og for bas; i tæt musik er den mindre sikker.'],
['Toner og klang','Toneklasse (chroma)','En af de 12 toner, C til B, uanset oktav. A2, A3 og A4 er alle toneklassen A.'],
['Toner og klang','Basens og melodiens tone (to lag)','Programmet finder to toner: den kraftigste (ofte bassen eller en kick, under 180 Hz) og den kraftigste over 180 Hz (melodien), efter at bassen er filtreret væk, så en høj bas ikke skjuler en svagere melodi. Lyd i 3D tegner de to lag som striber. Er der ingenting over 180 Hz, er der ingen melodi.'],
['Toner og klang','Tonesikkerhed','Hvor sikkert programmet har fundet en grundtone (0 til 1). Lav ved støj og tæt musik.'],
['Toner og klang','Tonestyrke','Hvor dominerende den stærkeste toneklasse er (0 til 1). Høj ved en enkelt tone, lav ved støj.'],
['Toner og klang','Tonebegivenhed','Meldingen om, at en ny tone er begyndt: den har stået sikkert i mindst 50 ms. Bruges til at føde levende kopier.'],
['Toner og klang','Klang (timbre)','Det, der får to instrumenter til at lyde forskellige, selv om de spiller samme tone. Måles som dissonans, overtonerigdom, ulige overtoner og spredning.'],
['Toner og klang','Overtoner','De svagere toner, der klinger med grundtonen (2, 3, 4 gange frekvensen osv.). Mange overtoner giver en lys, rig klang.'],
['Toner og klang','Ulige overtoner','Andelen af overtonerne, der er ulige (1, 3, 5 ...). Høj for en firkantbølge og for en klarinet.'],
['Toner og klang','Dissonans','Hvor meget toner i lyden "skurrer" mod hinanden. En lille sekund er dissonant, en oktav eller en kvint er det ikke.'],
['Toner og klang','Spektral spredning','Hvor bredt lyden fordeler sig omkring tyngdepunktet. Støj er bred, en ren tone er smal.'],
['Forbindelser','Forbindelse','En kobling fra et lydtræk til en effekt eller en egenskab. Har tærskel, gain, attack, release, kurve og pause.'],
['Forbindelser','Tærskel','Hvor højt lydtrækket skal op, før forbindelsen tænder. Under tærsklen sker der ingenting.'],
['Forbindelser','Gain','Hvor kraftigt effekten svarer, når den er tændt.'],
['Forbindelser','Attack','Hvor hurtigt forbindelsen tænder (millisekunder). Lav = skarp, høj = blød indfasning.'],
['Forbindelser','Release','Hvor langsomt forbindelsen slukker igen (millisekunder). Høj = lang efterglød.'],
['Forbindelser','Envelope','Det glattede tal (0 til 1), der kommer ud af en forbindelse og styrer effekten.'],
['Forbindelser','Kurve','Kontrast mellem svage og stærke værdier: over 1 trykker svage ned, under 1 løfter dem.'],
['Forbindelser','Pause (gap)','Mindste tid mellem to klodser eller fødsler, så ét langt slag ikke giver en strøm.'],
['Forbindelser','Invertér, Slå fra, Solo','Invertér vender forbindelsen om (tænder, når lydtrækket er stille). Slå fra gør den tavs. Solo gør alt andet tavst, så du ser, hvad den ene gør.'],
['Forbindelser','Master','Skalerer alle forbindelser på én gang.'],
['Forbindelser','Kobl via klik','Tryk på knappen ved en egenskab, og klik derefter på et lydtræk i EQ eller Radial Mesh. Det er ikke maskinlæring: programmet lytter ikke selv.'],
['Forbindelser','Kør Auto','Kræver en analyseret sang. Vælger op til tre slag-lydtræk, sætter tærskler og kobler flydende effekter. Erstatter alle dine forbindelser og gemmer intet af sig selv.'],
['Forbindelser','Radial Mesh (spindelvævet)','Alle forbindelser på ét sted: lydtræk yderst, effekter og figurer inderst. Træk fra et lydtræk til en effekt for at koble.'],
['Figurer og effekter','Figur','En ting på scenen, du kan flytte, give navn og styre: den har en placering og op til 6 lag (hvert lag har en form og egenskaber som størrelse, farve, pigge og drejning). Der kan være op til 32 figurer (mange synlige gør programmet langsommere). Hed før objekt. Det er ikke en lydkilde. Forskellen på figur og form står i manualen.'],
['Figurer og effekter','Lag','En del af en figur. Ét lag har én form og sine egne egenskaber, og en figur kan bestå af op til 6 lag oven på hinanden, fx en kugle, en ring og en pigkrans.'],
['Figurer og effekter','Tilfældigt (forbindelser)','Tre knapper i Værksted laver tilfældige forbindelser i hver sin kategori: Tilfældige slag (kick, snare, hihat, bas og flux til puls, burst, ring, glød, dæmpningsringe, ekko, klodser og sjældent ryst og strobe), Tilfældige flydende (blødere lydtræk til farve, bølge, fart, zoom og lignende) og Tilfældige figur-egenskaber (egenskaber på dine synlige figurer). Antal vælger, hvor mange; Behold mine lægger til, Erstat i kategorien fjerner først dine egne i netop den kategori. Et frø gør valget gentageligt, og Fortryd tilfældigt sætter alt tilbage (op til 10 trin). Radial Mesh har Tilfældigt (alle) til alle tre kategorier på én gang.'],
['Figurer og effekter','Figur-generator','Laver op til 32 figurer på én gang, med tilfældige lag. Du vælger antal, lag pr. figur (1 til 6), om formerne er tilfældige af de 14 eller kun cirkler, om farverne følger sangens toneart eller er tilfældige, tekstur (ingen, tilfældig eller én type), om nogle lag skal være ringe af kopier, og om figurerne skal kobles tilfældigt til musikken. Behold lægger figurerne til dine egne; Erstat sletter først dine figurer (ikke klods-modellen). Et frø gør valget gentageligt, og Fortryd figurer sætter alt tilbage (op til 10 trin). Findes i Form-editoren.'],
['Vinduer og topbar','Prik ved lydtræk (Dublet)','I Preview-dubletten har et lydtræk, der har en forbindelse, en lille farvet prik til højre for navnet (lige før tallet). Farven er lydtrækkets egen (som i Radial Mesh), og prikken lyser stærkt og får en glød, mens forbindelsen er aktiv; er den stille, er prikken svag. Lydtræk uden forbindelse har ingen prik. Tallet til højre er stadig antallet af forbindelser.'],
['Figurer og effekter','Bane: vis, færdige baner og 16 spor','Banen (gulv, spor, trefferlinje, slange og klodser) kan slås helt fra med Vis bane, så billedet er tomt, og effekter og figurer stadig tegnes. Færdige baner i panelet Bane og klods: Tom bane, Bane med 4 spor (kører som normalt) og Bane med 16 spor (mindre klodser, så de passer, og klodsfart 0,4, så rejsetiden er længere). Antal spor går op til 16, og klodsfarten ned til 0,1 (cirka 9 sekunders rejsetid). Klodsen kan tegnes som en figur (model) med lag, former, tekstur og gentagelse.'],
['Vinduer og topbar','Live preview: format og fuld skærm','I overskriften på Live preview sætter listen Format vinduet til 16:9 bredt, 9:16 højt, 1:1 kvadrat, 4:3 eller 3:4 højt ud fra den nuværende bredde (vinduet kortes ned, så det passer i arbejdsområdet; du kan stadig trække i hjørnet), og knappen Fuld skærm viser Live preview i browserens egen fuld skærm (Escape afslutter).'],
['Hjælp til tilgængelighed','Tastatur i Mesh, Node-editoren og 3D','Radial Mesh, Node-editoren og Lyd i 3D kan bruges uden mus: Tab ind i lærredet. I Mesh og Node-editoren flytter piletaster rundt (Mesh: venstre og højre på ringen, op og ned skifter ring; Node-editoren: op og ned i en kolonne, venstre og højre skifter kolonne), Enter vælger og kobler (først et lydtræk, så et mål), Escape afbryder, Delete sletter den valgte forbindelse, og [ og ] vælger forrige og næste forbindelse. I Mesh går Z ind i en figur. I Lyd i 3D vælger 1, 2 og 3 kamera, og piletasterne skifter indstillinger. Tasterne bruges ikke til klaveret, mens et lærred har fokus. Hvert skridt siges i statuslinjen, som skærmlæsere oplæser.'],
['Hjælp til tilgængelighed','Tryk og hold (berøringsskærm)','En musetip vises ikke på en berøringsskærm. Hold en finger på noget med en forklaring i et halvt sekund, så vises forklaringen i en boble i cirka 3,5 sekunder. Flytter du fingeren, eller løfter du den for tidligt, sker der intet. Har boblen været vist, bliver selve trykket ikke til en handling.'],
['Lyd og måling','Anslagsskarphed og Legato-grad','To analysekilder i gruppen Artikulation: Anslagsskarphed (hvor skarpt lyden begynder, 1 for et slag, næsten 0 for en blød opbygning) og Legato-grad (hvor vedvarende og stabil lyden er, tæt på 1 for en pad eller en klokke med lang efterklang). Regnet ud af lydstyrken, ens for filer og live, kun prøvet på syntetiske lyde. Brug dem til at lade lydens artikulation styre en effekt eller en figurs egenskab.'],
['Lyd og måling','Peak og Dominerer (eksperimentelle)','Fem eksperimentelle analysekilder (gruppen Eksperimentel: ikke prøvet på rigtig musik): Peak (den højeste topamplitude i et kort vindue) og Dominerer for bas, mid, høj-mid og brilliance (det område, der stikker mest ud lige nu, giver 1). De er kun prøvet på syntetiske lyde.'],
['Lyd og måling','Lydens karakter (Energi og Lyshed)','To langsomme kilder: Energi (0 rolig, 1 energisk) og Lyshed (0 mørk, 1 lys), lagt sammen af eksisterende lydtræk og glattet over cirka 2 sekunder. Lydens karakter, ikke en stemning; vægtene er ikke sammenlignet med mennesker.'],
['Lyd og måling','Stereo (panorering, bredde, faselighed)','Tre analysekilder for lydfiler: Panorering (0 venstre, 1 højre), Stereobredde (0 samme lyd i begge sider eller kun i den ene, 1 helt forskellige lyde i hver side) og Faselighed (1 ens fase, 0 modfase). Kun for lydfiler.'],
['Figurer og effekter','Discokugle','En form (den 16.): en drejende kugle af spejlfliser med lysstråler, lysprikker og glimt. Glimt kan kobles til kick, snare og hihat, men holdes under en grænse for glimt i sekundet; Rolig og Lysshowets styrke dæmper det hele.'],
['Figurer og effekter','Hold i stangen','En stilling for danseren: den ene arm tager fat i stangen, hun læner sig mod den, og ét ben hager ind. Findes sammen med Stang, vis og Stang, side.'],
['Figurer og effekter','Danser','En ny form: en stiliseret, påklædt kvinde i tegneseriestil på et dansegulv, tegnet med programmets egen kode. Hendes bevægelser (knæbøj, hop, arme, hoved, hofte, hår, kjole, smil) styres af lyden gennem almindelige forbindelser, og udseendet (krop, ansigt, hår, tøj, gulv) kan justeres med cirka 50 egenskaber. Tryk Eksempel: danser i Form-editoren; Dansemapping er en enkel visning over forbindelserne.'],
['Figurer og effekter','Numre på vinduer og bokse','Små numre på vinduer (W1 til W9), dialoger (D1 til D5), panelerne på siden (P1, P2 …) og bokse med overskrift (fx W6.3), så vi kan tale om dem. Kortet i manualen viser dem alle. De kan slås fra under Indstillinger.'],
['Lyd og måling','Hold og tone-port','Hold (pause uendelig) lader en effekt blive stående på sit niveau, når lyden går under tærsklen, til næste lyd kommer. Port lader en forbindelse kun virke, når en anden kilde (fx Tonesikkerhed) er over en grænse. Begge sættes på forbindelsen i Mapping; Ryd hold nulstiller alle hold-niveauer.'],
['Lyd og måling','Test lyden og fejllog','Hvis lyden mangler: Indstillinger, Lyd og fejl. Test lyden spiller en tone på 440 Hz gennem programmets egen udgang og viser lydstatus (startet, kører eller venter, lydstyrke og lydløs). Fejllogen gemmer de seneste 20 fejl i programmet og kan kopieres.'],
['Lyd og måling','Taktfølger (live)','Når Lyd ind (eller Musik-generatoren) er tændt, gætter programmet tempoet i realtid og viser det (slag i minuttet) med en lampe, der blinker på slaget. Den skal bruge et par sekunder med tydelige slag, kan tælle dobbelt eller halvt så hurtigt som dig (brug ÷2 og ×2) og styrer endnu ikke figurer, klodser eller Show. Det er forarbejde til en fuld live-indgang.'],
['Lyd og måling','Lyd ind (live)','Chippen Lyd ind tager lyd udefra ind, så billedet reagerer på musik i rummet og ikke kun på en fil: en mikrofon eller linjeindgang, eller lyden fra et andet faneblad. Lyden går ind i analysen, men spilles ikke i højttalerne (så der ikke opstår hyletone). Niveauet justeres, og en måler viser det. Starter du en fil, slukkes Lyd ind. Kræver tilladelse, og virker ikke i en udgivet side, kun i filen på din computer.'],
['Lyd og måling','Optag video','Chippen Optag øverst til højre optager det, udgangsvinduet viser (Live preview, Radial Mesh eller Lyd i 3D), og lyden fra den fælles udgang, som en videofil (webm, eller mp4 hvis browseren kun kan det). Lyden optages før volumen, så den ikke afhænger af, hvor højt du lytter. Indstillinger: opløsning, billeder i sekundet, med eller uden lyd og højeste længde (1, 5, 10 eller 30 minutter, fordi optagelsen ligger i hukommelsen). Bagefter vises en dialog med en afspiller og et link til at gemme filen. Faneblad skal være synligt, mens du optager.'],
['Vinduer og topbar','Snap af vinduer','Træk et vindue til en kant eller et hjørne af arbejdsområdet (under topbaren), eller tryk ▦ i overskriften: venstre og højre kant giver halve vinduer, hjørnerne giver kvarte, øverste kant maksimerer, og nederste kant giver den nederste halvdel. Et blåt felt viser, hvor vinduet lander. Trækker du i et snappet vindue, får det sin gamle størrelse igen.'],
['Vinduer og topbar','Layouts','Menuen Vinduer, Layouts: gem alle vinduers placering, størrelse, minimering og maksimering under et navn (op til 20 egne), og hent dem igen. Fem færdige følger med: Standard, Preview stor, Preview og Form-editor side om side, Fire vinduer (2 × 2) og Preview øverst og tidslinje nederst. De færdige minimerer de andre vinduer til dock\'en i kanten.'],
['Vinduer og topbar','Topbarens størrelse og dock','Menuen Vinduer, Topbar: Fuld, Kompakt (halv højde; statuslinjen vises kort, når der sker noget) og Minimal (kun Afspil og Fest!; knappen ☰ viser resten). Dock: Fastgjort øverst eller Skjul automatisk (topbaren kommer frem, når musen er helt oppe i toppen, eller du tabber derop).'],
['Vinduer og topbar','Maksimér og gendan et vindue','Maksimér fylder arbejdsområdet under topbaren. Gendan, Escape eller et dobbeltklik på vinduets overskrift sætter det tilbage. Under Fest! skjules topbaren, og vinduet dækker hele skærmen; Escape eller Stop fest i vinduets overskrift afslutter Fest!. Et vindue kan ikke trækkes så højt op, at overskriften ligger bag topbaren.'],
['Figurer og effekter','Radial Mesh eller Node-editoren','Radial Mesh og Node-editoren laver de samme regler i den samme liste. Radial Mesh er overblikket (alle regler som et net, en figur er én prik); Node-editoren er det præcise værktøj: Noder viser hver regel som en kasse med linjer, og Matrix viser alle regler i ét gitter med lydtræk som rækker og mål som kolonner. Knappen Kobl via klik i Form-editoren: klik bagefter på et lydtræk i EQ eller Radial Mesh.'],
['Figurer og effekter','Perfect 1 og Perfect 2','Perfect 1 og Perfect 2 (knapper i Form-editoren) bygger en opsætning med ti figurer, en pr. lydtype (kick, snare, hihat, bas, pad, pluck, klokke, riser, vokal og arpeggio), med form, farve, action og forbindelser fra lydtræk. Perfect 1 er enkel, Perfect 2 har flere lag, teksturer, gentagelser, en 3D-form og flere scene-effekter. De lægges til dine figurer og står på scenen. Knappen ? Lyd og vision åbner manualens afsnit om, hvilke lyde der passer til hvilke former, farver og actions.'],
['Figurer og effekter','Placering af en figur','To felter, x og y (0 til 1), i Form-editoren sætter figurens placering, også mens den ligger i kassen. Du kan også flytte den med Flyt effekter i Live preview, men kun når den står på scenen. Nulstil pos. sætter den tilbage.'],
['Figurer og effekter','Ny figur','Knappen Nyt i Form-editoren laver en ny figur på et frit sted, så den ikke ligger oven på en anden. Den ligger i kassen (skjult), til den er klædt på: du bygger den i Form-editoren (den ses forstørret dér) og forbinder den, og trykker så Læg på scenen. Vil du hellere have, at nye figurer står på scenen med det samme, så fjern fluebenet Nye figurer starter i kassen i Indstillinger. Sletter du den sidste figur, bliver scenen tom, og en tom, skjult Figur 1 ligger i kassen, så der altid er en at redigere.'],
['Figurer og effekter','Vis figurer','Fluebenet Vis figurer i panelet Bane og klods slår alle figurer (Morgenstjernen, Pigkuglen og de andre) fra i Live preview på én gang. En figur står nemlig stille på skærmen, også når alle forbindelser er slået fra: forbindelserne får den kun til at bevæge sig, ikke til at komme og gå. En enkelt figur skjules med Vis i Live preview i Form-editoren.'],
['Figurer og effekter','Tekstur','Et mønster inde i et lags form: striber, prikker, tern, bølger eller støj. Typen vælges ved siden af Form i Form-editoren; Styrke (0 til 1), Størrelse og Vinkel er egenskaber i kassen Tekstur, og de kan kobles til lydtræk. Mønstret tegnes i en mørkere (eller, for prikker, lysere) nuance af lagets egen farve og klippes til formen. Virker ikke på Pigkugle 3D og Terning 3D, og springes over ved mere end 8 kopier.'],
['Figurer og effekter','Gentagelse rundt om figuren','Et lag kan gentages 1 til 32 gange i en ring rundt om figurens midte, med fire egenskaber: Antal, Ringens radius (andel af højden), Ringens drejning og Vend (0 lader kopierne stå lige op, 1 lader dem vende udad som solstråler). Eksempel: en lille stjerne gentaget 12 gange rundt om et hjerte. Med radius 0 ligger kopierne oven på hinanden og giver et kalejdoskop. Alle fire kan kobles til lydtræk. Med mere end 8 kopier slås gløden fra, fordi mange kopier ellers kan gøre programmet langsomt.'],
['Figurer og effekter','Form','Typen af tegning på ét lag i en figur: Cirkel, Rektangel, Ring, Polygon (en trekant er en polygon med tre punkter), Stjerne, Pigkugle, Hjerte, Halvmåne, Kors, Blomst, Bølge, Spiral, Pigkugle 3D eller Terning 3D. Formen bestemmer, hvilke ekstra egenskaber laget har (en Ring har Tykkelse, en Stjerne har Punkter og Indre). Du vælger form pr. lag i Form-editoren. Forskellen på figur og form: en figur er hele tingen på scenen, en form er tegningen på ét af dens lag.'],
['Figurer og effekter','Egenskab (fra og til)','Hver egenskab har en fra-værdi (lydtrækket er stille) og en til-værdi (lydtrækket er fuldt). En forbindelse flytter værdien mellem dem.'],
['Figurer og effekter','Afstand','0 er nær, 1 er fjern. Fjerne ting tegnes mindre og svagere. Dybde i 2D, ikke en måling af, hvor lyden kommer fra.'],
['Figurer og effekter','Model og levende kopi','En levende figur er en model (den vises kun i form-editoren). En levende kopi er én kopi af den, der fødes, lever og dør. Før hed de skabelon og forekomst.'],
['Figurer og effekter','Fødsel','Hvornår en levende kopi fødes: ved et anslag (en forbindelse) eller af en fundet tone. Udseendet fastfryses ved fødslen.'],
['Figurer og effekter','Effekt','Noget, der virker på hele billedet eller på et punkt: Lys-puls, Baggrundsfarve, Partikel-burst, Glød, Chokbølge, Zoom, Strobe, Partikelsky, Dæmpningsringe og flere.'],
['Figurer og effekter','Prioritet (fokus)','De kraftigste levende kopier står i fokus, de andre dæmpes.'],
['Figurer og effekter','Relationer','Tynde linjer mellem levende kopier, der hører sammen: samme toneklasse, en kvint eller født samtidig.'],
['Figurer og effekter','Halespor','En hale af udtonende cirkler efter hver levende kopi.'],
['Figurer og effekter','Dybdeskarphed','Fjerne ting er slørede. Dyrt, så den kræver et kvalitetsniveau, der tillader det.'],
['Figurer og effekter','Glød','Sløring på kanten af en form (shadowBlur). Dyr; slået fra som standard. Er ikke det samme som effekten Glød.'],
['Figurer og effekter','Slange','En lang afrundet slange langs begge sider af banen, som bølger til lydtrækket og kan skifte farve.'],
['Figurer og effekter','Klods og bane','En klods er en markering, der kommer ned ad banen og rammer trefferlinjen på slaget. Banen har 1 til 8 spor.'],
['Opsætninger','Opsætning','Forbindelser, master, figurer, positioner, bane og lyd, der kan gemmes og hentes.'],
['Opsætninger','Opsætning','En af de 14 indbyggede opsætninger (Standard, 1 til 13). De er låste og kan ikke overskrives.'],
['Opsætninger','Mine opsætninger','Dine 20 egne pladser, A til T. Gem, hent, slet og lås dem (koden til lås står i manualen).'],
['Kvalitet og ydelse','Kvalitetsniveau','Hvor meget programmet må tegne på én gang, så det bliver ved med at køre flydende, især på en stor skærm. Der er fem valg: Disco (det, du starter med: glød er slået fra, og der er en grænse for, hvor mange levende kopier, partikler og ekkoer der tegnes), Undervisning (lidt blødere), Spar (halv opløsning og 30 billeder i sekundet, til en svag computer), Fuld (ingen grænser ud over programmets egne) og Egen (du stiller hver grænse selv). Det ændrer ikke, hvordan din kunst er sat sammen, kun hvor tungt den tegnes. Derfor huskes valget på din computer (i indstillingerne) og følger ikke med, når du gemmer eller henter en opsætning.'],
['Kvalitet og ydelse','Kvalitetsregulator','Kan slås til (er fra som standard). Bliver billederne for langsomme, skruer den selv ned i højst fire trin (først glød, så ekkoer, partikler og levende kopier, til sidst opløsningen) og op igen, når der er plads. Den går aldrig over det niveau, du har valgt.'],
['Kvalitet og ydelse','Måletest','Tegner syv scener på din skærm i cirka 30 sekunder og anbefaler et kvalitetsniveau. Den rører ikke din opsætning. Gør Live preview så stort, som du vil bruge det, før du kører den.'],
['Opsætninger','Fest!','Én knap: indlæser en færdig opsætning, vælger kvalitet, slår regulatoren til, starter lyden og gør Live preview til fuld skærm. Stop fest gendanner.'],
['Opsætninger','Random alt','Opsætning 13: alle effekter koblet og 4 til 8 forbundne figurer, ny hver gang. Kan skifte automatisk.'],
['Vinduer og topbar','Mini-vindue','Tryk − i et vindues bjælke: det bliver et slankt kort i siden med få indstillinger. + sætter det tilbage.'],
['Vinduer og topbar','Ordn vinduer','Sætter vinduerne i to søjler uden overlap.'],
['Vinduer og topbar','Dublet','Et ekstra Live preview, hvor du kan trække figurer rundt og forbinde lydtræk til effekter og egenskaber direkte. Kan køre i lavere opløsning.'],
['Vinduer og topbar','Topbaren og menuerne','Hovedlinjen har det, du bruger hele tiden (Vælg lydfil, Afspil, afspilleren med volumen og niveaumåler, Gentag, Fest!) og tre statusknapper (Sikker visning, Udgangsvindue, Sort skærm). Resten ligger i fem menuer: Opsætning, Show, Vinduer, Lyd og ydelse og Hjælp. Kun én er åben ad gangen; Escape eller et klik udenfor lukker den, og en grøn prik betyder, at noget i den er tændt.'],
['Vinduer og topbar','Felternes farver','De felter, hvor du skriver eller vælger noget, har deres egne farver, så teksten er til at læse. Indstillinger har fire valg: Neon-lilla (standard: lyse lavendelfelter med mørk lilla tekst og en lilla glød ved valg), Mørke felter, Lyse felter og Følg temaet.'],
['Vinduer og topbar','Manual','Menuen Hjælp, Manual: en brugermanual, en teknisk manual og en del om visionen og de forklaringer, vi har givet. Den har en indholdsfortegnelse og et søgefelt. Før hed den guiden.'],
['Lyd og måling','Gamle navne','Lydtræk hed før bånd og kilde, figur hed før objekt, og Slag, dyb (kick), midt (snare) og høj (hihat) hed før Kick, Snare og Hihat.'],
['Figurer og effekter','Placering (x, y, z)','Hvor en figur eller levende kopi står: x er sidelæns, y er op og ned, z er afstand. Ved fødsel kan hver være fast, tilfældig, et lydtræk, toneklasse eller tonehøjde.'],
['Kvalitet og ydelse','Billedhastighed (fps) og opløsning','Hvor mange billeder i sekundet og hvor mange punkter Live preview tegner. Lavere tal gør programmet lettere på en svag computer. Styres af kvalitetsniveauet.'],
['Opsætninger','Opsætning 1 og 2','To hurtige pladser (de to første af Mine opsætninger), så du kan skifte mellem to udgaver med ét tryk (Sammenlign 1 ↔ 2).'],
['Vinduer og topbar','Live preview','Det, spilleren ser: effekter og figurer, der reagerer på musikken. Her kan du flytte dem med Flyt effekter.'],
['Vinduer og topbar','Lydtræk over tid, EQ-visualizer og Analyse','Tre vinduer, der viser musikken: lydtræk som baner over tid, søjler med tærskel for hvert lydtræk, og log-spektrum, toneklasser og klang.'],
['Show og rytme','Show (koreograf)','Programmet laver en opsætning til netop den analyserede sang (Rolig, Balanceret eller Vild): lydtræk til effekter og figurer ud fra sangens egne tal, og en kontrol af, at intet er dødt eller altid tændt. Regler og tal, ikke kunstig kreativitet: programmet hverken hører eller ser resultatet.'],
['Show og rytme','Tempo (BPM) og taktslag','Slag i minuttet og de enkelte taktslag, fundet i en analyseret lydfil (ikke i generatorens live-lyd). Er sikkerheden lav, siges det. Tempoet kan være det halve eller dobbelte af det, man selv tæller.'],
['Show og rytme','Taktslag, Takt og Taktfase (lydtræk)','Tre lydtræk fra taktslagene i en lydfil: Taktslag er et lysglimt på hvert slag, Takt (første slag) kun på det første slag i hver takt (et gæt), og Taktfase vokser fra 0 til 1 mellem to slag, så den kan få noget til at dreje en gang pr. slag.'],
['Lyd og måling','Volumen, mute og niveaumåler','Skyderen Volumen (under topbaren) gælder al lyd: nummeret, generatoren og lydlaget. Den er kvadratisk, så den føles jævn, og står i dB (0 dB er fuld). Lyd/Lyd fra slår lyden fra og til. Niveaumåleren viser styrken af det, der spilles efter volumen: grøn er fint (op til −18 dB), gul er højt (op til −6 dB), og rød øverst (over −6 dB) betyder, at lyden er tæt på at klippe; en rød markering yderst til højre bliver stående et sekund efter et klip. Volumen og mute huskes.'],
['Lyd og måling','Spol, stop og tastaturgenveje','Under topbaren står en afspiller med Start, −5 s, Stop, +5 s og en positionsskyder (træk for at gå et sted hen). Genveje, når du ikke skriver i et felt: mellemrum = afspil eller pause, Home = til start, venstre og højre pil = 5 sekunder (Shift: 1 sekund), op og ned pil = volumen, M = lyd fra og til. De virker også, mens computertastaturet spiller klaver, for klaveret bruger kun bogstaverne A til P og Æ. K og S markerer kick og snare i tuningen, når klaveret er slået fra.'],
['Vinduer og topbar','Knappernes farver','En knap, du trykker på, lyser kort blå. Så fortæller farven, hvad der skete: grøn med ✓ betyder, at det virkede; gul med ! betyder, at noget manglede (fx ingen lydfil), og rød med ✕, at det mislykkedes; blå uden mærke betyder, at knappen ikke ændrede noget, man kan se. En knap, der er tændt (Flyt effekter, Dublet, Lyd i 3D, Fest, Afspil, Lyd fra), har en fast grøn kant. Kobl via klik pulserer gult, mens den venter på dig.'],
['Vinduer og topbar','Udgangsvindue, sort skærm og hold skærmen tændt','Udgangsvindue åbner et lille vindue, der som standard spejler Live preview, men som også kan vise Radial Mesh eller Lyd i 3D (valget Udgangsvinduet viser i Vinduer-menuen, eller knappen Vis på udgang i Radial Mesh-vinduet), med bevaret billedformat (sorte kanter). Træk det over på projektoren, og dobbeltklik eller tryk F i det for fuld skærm; musemarkøren skjules, når du ikke rører den. B giver sort skærm (også i selve vinduet), og tryk B igen for billedet. Programmet holder skærmen tændt, mens vinduet er åbent eller Fest er i gang (hvis browseren kan). Live preview tegnes i en højere opløsning, så billedet ikke er sløret på en stor skærm (højst 2 gange). Sikker visning gælder også her. Blokerer browseren pop-up-vinduer, siger programmet det.'],
['Vinduer og topbar','Sikker visning','Slået til fra start. Programmet måler lysstyrken i det tegnede billede og tæller blink efter retningslinjen (WCAG 2.3.1: højst tre blink i sekundet, hvor et blink er et par modsatrettede skift på mindst 0,1 i relativ luminans, når den mørkeste er under 0,8). Kommer der for mange, dæmpes de lyse effekter (Strobe, Glød, Lys-puls, Chokbølge og Burst) lige så meget, som der skal til, og slippes langsomt igen. Strobe er højst 0,24 hvid. Ryst og zoom halveres, og dæmpes til 40 %, hvis dit system beder om mindre bevægelse. Det er en hjælp, ikke en garanti. At slå den fra kræver en bekræftelse. Knappen Sikker visning (række 2) og Indstillinger styrer den.'],
['Lyd og måling','Tolerance (tuning)','Hvor langt (i millisekunder) et af dine tryk K eller S må ligge fra et slag, detektoren fandt, for at tælle som et træf. Dine tryk er forsinkede, så 90 ms er et godt udgangspunkt; 30 ms er meget strengt og 200 ms meget løst. Den ændrer kun målingen i Detektions-tuning (hit-rate, falske alarmer og forslag til tærskel), ikke billedet. Skyderen står i Detektions-tuning.'],
['Lyd og måling','Zoom, klip og sløjfe på tidslinjen','Lydtræk over tid kan zoomes: hjulet zoomer omkring musen (Shift eller sidelæns hjul panorerer), knapperne Zoom + og Zoom − zoomer omkring midten, og Hele sangen viser alt. Mindste visning er 0,25 sekund, så du kan arbejde med små klip. Træk på tidslinjen (eller tryk A og B ved afspilningsmarkøren) for at vælge et klip; det gentages uden hak i lyden (Sløjfe). Et klik udenfor klippet slår sløjfen fra. Følg lader visningen følge afspilningen.'],
['Lyd og måling','Snap (taktslag og tid)','Når et klip vælges, kan kanterne snappe til nærmeste taktslag, første slag i takten eller et kvart sekund. Taktslag og takt kræver en analyseret lydfil med et sikkert tempo; uden dem snappes der ikke. Tempoet kan rettes med Halvér, Fordobl og Tap-tempo i Show-panelet.'],
['Lyd og måling','Gentag nummeret','Når en lydfil er spillet til ende, starter den forfra af sig selv, så showet og Lyd i 3D bliver ved. Slået til fra start; slå det fra med afkrydsningen Gentag ved siden af Afspil eller under Indstillinger. Kort pause (en brøkdel af et sekund) ved genstarten.'],
['Show og rytme','Fortryd show','Før et show eller en sang-pakke erstatter dine forbindelser og figurer, gemmes det, du havde. Knappen Fortryd sidste show sætter det tilbage. Der gemmes ét ad gangen, og det huskes, også hvis siden lukkes.'],
['Show og rytme','Halvér, fordobl og tap-tempo','Tempoet kan være det halve eller dobbelte af det, du tæller. Halvér og Fordobl regner taktslagene om. Tap-tempo: tryk i takt (mindst 4, jævnt); passer tallet til analysen som ½, 1 eller 2 gange, rettes tempoet. Første slag nu sætter, hvilket taktslag der er første slag i takten.'],
['Show og rytme','Figurer, der kommer og går','I et show har hver figur en synlighed (0 til 1) i hver slags sektion, og de kommer ind og går ud med en glidende overgang ved hver sektionsgrænse. Kerne og Glimt kommer kun ved højdepunkter, Hjerte er der altid. En figur, der er væk, føder ingen levende kopier. Tabellen under Show kan rettes. Gælder kun, mens en lydfil spiller, og når Følg sangens opbygning er slået til.'],
['Show og rytme','Farveskift pr. sektion','Hver slags sektion kan flytte alle figurernes farver et antal grader (−180 til 180) rundt på farvehjulet, så et højdepunkt får en anden farvepalet end en rolig del. Overgangen glider. Berører kun figurer, ikke effekter.'],
['Show og rytme','Sektionernes vægte','En tabel over, hvor kraftig hver rolle (rytme, slag, flyd, melodi, scene, ekstra) er i hver slags sektion (rolig, middel, høj, opbygning, nedtoning, intro, outro), fra 0 til 1. Udgangstallene er et gæt; du kan rette dem, og de gemmes med showet.'],
['Show og rytme','Sektion (opbygning)','En del af sangen med samme karakter: intro, rolig, middel, høj, opbygning, nedtoning eller outro. Findes ved at se, hvornår lyden ændrer sig. Sektionerne står som markører på tidslinjen.'],
['Show og rytme','Rolle (rytme, slag, flyd, melodi, scene, ekstra)','Hver forbindelse i et show har en rolle. En sektion skruer op og ned for rollerne: i et roligt stykke dæmpes rytme og slag, og ekstra (ryst, strobe, hale ...) slukkes; i et højdepunkt er alt tændt. Overgangen glider over 1,2 sekunder.'],
['Show og rytme','Toneart','Den toneart, sangen ligger tættest på, fundet ved at sammenligne sangens toneklasser med standardprofiler (fx A mol). Er sikkerheden lav, er det et dårligt gæt.'],
['Show og rytme','Sang-pakke','Showet gemt sammen med sangens navn og oversigt. Når samme fil vælges igen, kan det indlæses med ét tryk. Kan også kopieres som tekst.'],
['Show og rytme','Kontrol (døde forbindelser)','Efter at et show er lavet, køres hver forbindelse over hele sangen. En forbindelse, der næsten aldrig er tændt (død) eller næsten altid tændt, får flyttet sin tærskel, så den følger sangen.'],
['Generator','Toneart, skala og rod','Rod er grundtonen i tonearten (fx C), skalaen er rækken af toner, der passer sammen (fx dur eller mol). Tone-lyden og tonebegivenhederne følger dem.'],
['Figurer og effekter','Trefferlinje og spor','Trefferlinjen er stedet, hvor klodserne skal ramme på slaget. Hvert spor har sin farve og sine klodser.'],
['Generator','Generator, genre og swing','Musik-generatoren laver et mønster i en genre. Swing skubber hvert andet trin lidt bagud, så det groover.'],
['Reserveret (findes ikke endnu)','Lydkilde og lydobjekt','Et instrument eller en stemme (med en position). Programmet kan ikke finde dem. En figur er ikke en lydkilde.'],


['Reserveret (findes ikke endnu)','Stemning og energi','Valens (positiv eller negativ stemning) og arousal (energi). Planlagt; kan ikke måles pålideligt endnu.'],
['Reserveret (findes ikke endnu)','Kantpuls','En visuel puls i kanten af en figur. Ikke musikalsk vibrato. Planlagt, ikke bygget.'],
['Reserveret (findes ikke endnu)','Instrumentgenkendelse','At sætte navn på instrumenter. Kan ikke gøres pålideligt i blandet musik. Det tætteste, der er muligt, er en klangtype (slag, tone, støj).']];
const hesc=t=>String(t).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function hjUI(){const q=($('hj-find').value||'').trim().toLowerCase(),l=ORDBOG.filter(r=>!q||(r[1]+' '+r[2]+' '+r[0]).toLowerCase().includes(q));let h='',k='';
 l.forEach(r=>{if(r[0]!==k){k=r[0];h+='<div class="kat">'+hesc(k)+'</div><dl class="tm">'}h+='<dt>'+hesc(r[1])+'</dt><dd>'+hesc(r[2])+'</dd>'});
 $('hj-liste').innerHTML=h||'<p class="small">Ingen ord passer. Prøv et kortere søgeord.</p>';$('hj-info').textContent=l.length+' af '+ORDBOG.length+' ord. Mere står i Manualen.'}
$('hjbtn').onclick=()=>{hjUI();try{$('hj').showModal()}catch(e){}};$('hj-x').onclick=()=>{try{$('hj').close()}catch(e){}};$('hj-find').addEventListener('input',hjUI);hjUI();
/* ---- Tooltips: alle knapper får en forklaring, også dem der oprettes senere ---- */
const TIP_ID={play:'Afspil eller sæt den indlæste lydfil på pause. Knappen er slukket, til en fil er analyseret.',gbtn:'Åbn manualen: brugermanual, teknisk manual og vision, med søgning og indholdsfortegnelse.',sbtn:'Åbn indstillinger: tema, felternes farver, billedhastighed, Gentag, Sikker visning og Nulstil alt.',fest:'Én knap: indlæser en færdig opsætning, vælger kvalitet, slår regulatoren til, starter lyden og gør Live preview til fuld skærm.','mb-ud':'Vis Radial Mesh på udgangsvinduet (projektoren). Åbner udgangsvinduet, hvis det er lukket.','ud-btn':'Åbn et vindue til projektoren: det spejler Live preview med bevaret billedformat. Træk det over på projektoren, og dobbeltklik for fuld skærm. B: sort skærm.','ud-sort':'Sort skærm i udgangsvinduet (genvej: B, også i selve udgangsvinduet). Tryk igen for at få billedet tilbage.','tb-sikker':'Sikker visning: begræns blink til højst tre i sekundet og dæmp rystelser. Slået til fra start; at slå den fra kræver en bekræftelse.','tl-zi':'Zoom ind på tidslinjen (halvt så meget af sangen). Hjulet zoomer omkring musen.','tl-zo':'Zoom ud på tidslinjen (dobbelt så meget).','tl-fit':'Vis hele sangen på tidslinjen.','tl-a':'Sæt A (starten på et klip) ved afspilningsmarkøren. Snap gælder.','tl-b':'Sæt B (slutningen på klippet) ved afspilningsmarkøren, og start sløjfen. Snap gælder.','tl-loop':'Gentag klippet mellem A og B uden hak i lyden. Slås fra, hvis du klikker udenfor klippet.','tl-zloop':'Zoom ind, så klippet fylder tidslinjen.','tl-ryd':'Ryd A og B og slå sløjfen fra.','pl-start':'Til start af nummeret (genvej: Home).','pl-back':'Spol 5 sekunder tilbage (genvej: venstre pil; Shift giver 1 sekund).','pl-fwd':'Spol 5 sekunder frem (genvej: højre pil; Shift giver 1 sekund).','pl-stop':'Stop og gå til start.','pl-mute':'Slå lyden fra eller til (genvej: M). Gælder nummeret, generatoren og lydlaget.',hjbtn:'Åbn ordlisten: hvad ordene i programmet betyder, med søgning.',norm:'Skift mellem skalering pr. sang (Auto) og en fast reference, så lydtræk kan sammenlignes på tværs af sange.',rwin:'Sætter alle vinduer på plads i to søjler uden at overlappe.',mina:'Gør alle vinduer til mini-kort i siderne, eller sæt dem alle tilbage.',dubbtn:'Åbn eller luk Preview-dubletten: et ekstra Live preview, hvor du kan flytte figurer og forbinde lydtræk direkte.',mvbtn:'Slå til, så du kan trække effekter og figurer rundt i Live preview. Fra: de ligger fast.',mvrst:'Sæt alle effekter og figurer tilbage på deres standardplacering.',eqnew:'Opret en forbindelse fra det lydtræk, du har valgt i EQ-visualizeren (til effekten Glød, som du så kan skifte).',gp:'Start eller stop generatorens rytme.',gauto:'Lad generatoren lave et mønster i den valgte genre og tæthed.',gmut:'Fjern lidt af mønsteret tilfældigt, så det bliver luftigere.',gclr:'Ryd hele mønsteret.',gsend:'Render 8 takter af generatorens mønster og send dem til analyse i editoren. Tryk bagefter Afspil øverst.',octd:'Flyt klaviaturet en oktav ned.',octu:'Flyt klaviaturet en oktav op.',grec:'Optag det, du spiller på klaviaturet, ind i Lead-instrumentet i takt.',gkb:'Slå computerens tastatur til eller fra som klaver (A til L og W E T Y U O P).','mb-tilbage':'Gå tilbage fra figur-visningen til oversigten i spindelvævet.','mb-sa':'Gem det, du ser nu, som din opsætning A.','mb-sb':'Gem det, du ser nu, som din opsætning B.','mb-multi':'Slå Multi-styring til eller fra: en XY-pad, der flytter flere forbindelsers indstillinger på én gang.',mflow:'Vis lyset som små pulser, der løber fra lydtrækket til effekten, hver gang en forbindelse stiger.',mdel:'Slet den valgte forbindelse.',fnul:'Nulstil den valgte figur til en tom standardfigur (fjerner dens koblinger, beholder navn og placering).',fclr:'Fjern alle koblinger til det valgte lag.',swap:'Sammenlign: skift mellem opsætning 1 og 2.',add:'Tilføj en ny forbindelse (Bas til Lys-puls), som du så kan ændre.','ops-brug':'Hent den valgte opsætning. Ændringer i den nuværende opsætning, der ikke er gemt, går tabt.','ops-gem':'Gem det, du ser nu, på den valgte plads (spørger, hvis pladsen allerede har indhold).','ops-hent':'Hent den valgte plads.','ops-slet':'Slet den valgte plads (spørger to gange; låste pladser kan ikke slettes).','ops-laas':'Lås pladsen, så den ikke kan overskrives eller slettes, eller lås den op med koden.','show-figurer-nul':'Sæt figurernes optræden og farveskiftet tilbage til udgangsgættet.','show-fortryd':'Fortryd det sidste show eller den sidste sang-pakke: dine forbindelser og figurer, som de var lige før, kommer tilbage.','show-halv':'Halvér tempoet: analysen fandt det dobbelte af det, du tæller. Taktslagene regnes om.','show-en':'Tilbage til det tempo, analysen fandt.','show-dobbelt':'Fordobl tempoet: analysen fandt det halve af det, du tæller. Taktslagene regnes om.','show-tap':'Tryk i takt med musikken (mindst 4 gange, jævnt). Passer tempoet til analysen (som ½, 1 eller 2 gange), rettes det.','show-foerste':'Tryk lige på første slag i en takt, mens musikken spiller. Så sættes Takt (første slag) til netop det taktslag.','show-vaegt-nul':'Sæt alle sektionsvægtene tilbage til udgangsgættet.','show-rolig':'Lav et roligt show til den analyserede sang: få figurer og effekter, blød bevægelse. Erstatter forbindelser og figurer.','show-bal':'Lav et balanceret show til den analyserede sang. Erstatter forbindelser og figurer.','show-vild':'Lav et vildt show til den analyserede sang: mange figurer og effekter. Erstatter forbindelser og figurer.','show-gem':'Gem det aktuelle show til den valgte lydfil, så det kan indlæses igen, næste gang filen vælges.','show-hent':'Indlæs det show, der er gemt til den valgte lydfil.','show-slet':'Slet det show, der er gemt til den valgte lydfil.','show-kopi':'Skriv sang-pakken som tekst i feltet nedenfor, så du kan kopiere den.','show-ind':'Indlæs en sang-pakke fra teksten i feltet nedenfor.',rtbtn:'Åbn eller luk Routing-overblikket: alle forbindelser i tre kolonner (lydtræk, mål, figurer og kasser), ordnet så linjerne krydser mindst muligt. Klik på en knude for fokus.',rtx:'Luk Routing-overblikket (det kan åbnes igen under Vinduer).',mstor:'Skjul bjælkerne foroven og forneden i Radial Mesh, så nettet fylder hele vinduet. Tryk igen (Vis kontroller) for at få dem tilbage.',mfuld:'Vis Radial Mesh over hele skærmen, skarpt i skærmens fulde opløsning (også 4K). Escape afslutter.',dubx:'Luk Preview-dubletten (den kan åbnes igen med Dublet).','mb-auto':'Kør Auto: vælger lydtræk, tærskler og effekter ud fra den analyserede sang og erstatter alle forbindelser. Kræver en analyseret fil.','bench-start':'Tegn syv scener på din skærm og find ud af, hvilket kvalitetsniveau den kan klare (cirka 30 sekunder).','bench-stop':'Afbryd måletesten.','bench-brug':'Brug det anbefalede kvalitetsniveau.','bench-kopi':'Kopiér måletestens rapport (med grafikkort og skærm), så den kan sendes.',lmute:'Slå hele lydlaget fra uden at ændre andet.',auto:'Til: kører Auto-mapping af sig selv, hver gang en sang er analyseret.',autonow:'Foreslå regler ud fra figurerne på scenen og den analyserede sang. Forslagene vises som stiplede celler i matrixen; intet ændres, før du siger ja.',fast1:'Indlæs standardopsætningen: klodser på kick, snare og hihat (trommer-fokus).',fast2:'Indlæs en rolig, flydende opsætning uden hårde slag.',clr:'Ryd de K- og S-tryk, du har markeret i tuningen.',copy:'Kopiér den nuværende opsætning som tekst (JSON), så du kan gemme den eller sende den.',load:'Indlæs en opsætning fra teksten i feltet ovenfor.',gt1:'Brugermanual: sådan bruger du programmet.',gt2:'Teknisk manual: hvordan programmet virker indeni.',gt3:'Vision og forklaringer: hvad programmet er til, og hvad vi har aftalt.',gt4:'Alt: alle tre dele på én gang.','man-find':'Søg i hele manualen.',gx:'Luk manualen.','hj-x':'Luk ordlisten.','bd-nej':'Annullér: intet ændres.','bd-ok':'Bekræft.','s-reset':'Nulstil alt: sletter dine forbindelser, figurer og indstillinger (låste pladser bevares). Spørger to gange.','s-x':'Luk indstillinger.'};
const TKORT={play:'Afspil eller pause lydfilen.',mv:'Slå Flyt effekter til eller fra i Live preview.',mvrst:'Sæt effekter og figurer tilbage på deres standardplads.',fest:'Start eller stop Fest!',gp:'Start eller stop generatoren.',mesh:'Vis den valgte figur i spindelvævet.'};
function tipFor(b){const d=b.dataset,id=b.id,t=b.textContent.trim();
 if(id&&TIP_ID[id])return TIP_ID[id];
 if(b.classList.contains('mx'))return 'Gør vinduet til fuld skærm. Tryk igen (Gendan) for at sætte det tilbage.';
 if(b.classList.contains('pad'))return (typeof TR!=='undefined'&&TR[+d.r]||'Række '+(+d.r+1))+', trin '+(+d.s+1)+': klik for at tænde eller slukke trinet.';
 if(b.classList.contains('mt'))return 'Slå '+(typeof TR!=='undefined'&&TR[+d.m]||'rækken')+' fra eller til (mute).';
 if(b.classList.contains('key'))return 'Spil tonen '+noteNavn(440*Math.pow(2,(+d.k-69)/12))+' (tryk eller brug computerens tastatur).';
 if(d.ma){const a=d.ma;if(TKORT[a])return TKORT[a];if(a.startsWith('klik:')){const x=TIP_ID[a.slice(5)];return x?'Genvej: '+x:'Genvej til den rigtige knap.'}if(a.startsWith('gaa:'))return 'Gå til feltet med opsætningen som tekst (JSON) længere nede.'}
 if(d.gs)return 'Gem generatorens mønster på plads '+d.gs+' (af 5).';if(d.gl)return 'Hent generatorens mønster fra plads '+d.gl+' (af 5).';
 if(d.op){return({nyt:'Opret en ny figur.',dup:'Duplikér den valgte figur (med dens forbindelser).',slet:'Slet den valgte figur.',scene:'Læg den valgte figur på scenen, eller tag den af, så den ligger i kassen.',op:'Flyt figuren op i rækkefølgen.',ned:'Flyt figuren ned i rækkefølgen.',mesh:'Vis den valgte figur og det valgte lag i spindelvævet, så du kan trække forbindelser til dens egenskaber.'})[d.op]||'Handling på figuren.'}
 if(d.lag){return({nyt:'Opret et nyt lag på figuren.',dup:'Duplikér laget (med forbindelserne).',slet:'Slet laget (en figur skal have mindst ét).',op:'Flyt laget op (nederste lag tegnes først).',ned:'Flyt laget ned.'})[d.lag]||'Handling på laget.'}
 if(d.save)return 'Gem det, du ser nu (forbindelser, master, figurer, positioner, bane og lyd), som '+d.save+'.';if(d.load)return 'Hent opsætningen '+d.load+'.';
 if(d.kv)return (typeof Rytme.KVAL_TEKST==='object'&&Rytme.KVAL_TEKST[d.kv])||'Vælg kvalitetsniveauet '+t+'.';
 if(d.prov)return 'Hør lyden, så du kan indstille den (kræver, at lyden er slået til).';
 if(d.lyt)return 'Hør Suus-lyden i varianten '+t+': fire slag med et svagt tik.';
 if(d.mark)return 'Markér et '+(d.mark==='kick'?'kick':'snare')+'-slag i takt med musikken (eller tryk '+(d.mark==='kick'?'K':'S')+'). Bruges til at måle, hvor godt slagdetektoren rammer.';
 if(d.min!==undefined)return 'Fold forbindelsen sammen til en kompakt linje, eller fold den ud igen.';
 if(d.del!==undefined)return 'Fjern forbindelsen.';
 if(d.slot)return 'Vælg plads '+d.slot+'. Brug derefter Gem her, Hent, Slet eller Lås.';
 if(d.dp)return 'Kobl lydtrækket til denne egenskab.';
 if(d.act)return({slet:'Slet den valgte forbindelse.',fra:'Slå den valgte forbindelse fra eller til.'})[d.act]||'Handling på forbindelsen.';
 return t||b.getAttribute('aria-label')||'Knap';}
function tipAlle(rod){(rod||document).querySelectorAll('button:not([title]),button[title=""]').forEach(b=>{b.title=tipFor(b)})}
tipAlle(document);let tipT=null,tipN=[];/* v9.69: kun det nye får tip med det samme; alle knapper hvert 5. sekund (før: hele siden ved hver ændring, cirka 10 gange i sekundet) */new MutationObserver(ms=>{for(const m of ms)for(const n of m.addedNodes)if(n.nodeType===1)tipN.push(n);if(tipT||!tipN.length)return;tipT=setTimeout(()=>{tipT=null;const L=tipN;tipN=[];for(const n of L){if(!n.isConnected)continue;if(n.tagName==='BUTTON'&&!n.title)n.title=tipFor(n);tipAlle(n)}},300)}).observe(document.body,{childList:true,subtree:true});setInterval(()=>tipAlle(document),5000);
